function patternYearsPage(){const[,rid,pid]=section.split(':'),r=plan().rules.find(r=>r.id===rid),p=r.patterns.find(p=>p.id===pid),first=U.fy(note().start);return breadcrumb(esc(r.name)+'／'+esc(p.name)+'の年度別収入')+notice('手取りを入力した年度は最優先．分からない年度は年収幅と手取り率を入れると概算します．空欄の欄はパターンの基本設定を引き継ぎます．退職金はここで年収に混ぜず，受取予定として登録します．')+`<div class="actions">${button('複数年度をまとめて入力','pattern-fill',rid+':'+pid)}${button('退職金を登録','payout-add',rid+':'+pid)}${button('パターンへ戻る','patterns',rid)}</div><div class="card"><p class="hint">表は左右にスクロールできます．すべて年間の金額です．</p><div class="scroll" tabindex="0"><table class="mini-table"><thead><tr><th>年度</th><th>手取り・円</th><th>年収下限・円</th><th>年収上限・円</th><th>手取り率％</th><th>使用する年手取り</th></tr></thead><tbody>${Array.from({length:plan().years},(_,i)=>first+i).map(y=>`<tr><th>${y}</th>${['netAnnual','grossMin','grossMax','rate'].map(k=>`<td><input aria-label="${y}年度の${k}" data-pattern-year="${y}" data-rule="${rid}" data-profile="${pid}" data-key="${k}" ${k==='rate'?'data-number max="100"':'data-money'} min="0" type="text" inputmode="decimal" value="${esc(num(p.years?.[y]?.[k]))}" placeholder="基本設定"></td>`).join('')}<td data-net-preview="${y}">${money(X.net(p,y).amount)}${X.net(p,y).estimated?'（概算）':''}</td></tr>`).join('')}</tbody></table></div></div>`;}
