 'living-copy':key=>{const[rid,pid,iid]=key.split(':'),p=plan().rules.find(r=>r.id===rid).patterns.find(p=>p.id===pid),i=U.C(p.items.find(i=>i.id===iid));i.id=U.uid();i.name+='（コピー）';p.items.push(i);persist('生活費の費目を複製');render();},
