 'payout-add':payoutEditor,'payout-edit':payoutEditor,'payout-delete':key=>{const[rid,pid,id]=key.split(':'),p=plan().rules.find(r=>r.id===rid).patterns.find(p=>p.id===pid);if(confirm('退職金の受取予定を削除しますか？入力済み実績は残ります．')){p.payouts=p.payouts.filter(v=>v.id!==id);persist('退職金の予定を削除');render();}},
 'pattern-fill':key=>{const[rid,pid]=key.split(':'),p=plan().rules.find(r=>r.id===rid).patterns.find(p=>p.id===pid);modal('年度別の収入をまとめて入力',input('開始年度','from',year,'number','required min="1900" max="2200"')+input('終了年度','to',U.fy(note().start)+plan().years-1,'number','required min="1900" max="2200"')+amount('年間手取り（分かる場合）','netAnnual','','min="0"')+amount('年収下限','grossMin','','min="0"')+amount('年収上限','grossMax','','min="0"')+input('手取り率（％）','rate','','number','min="0" max="100"')+notice('対象年度の収入設定を，この内容で置き換えます．手取りが空なら年収幅と率から概算します．'),f=>{const a=U.N(f.get('from')),b=U.N(f.get('to'));if(b<a||b-a>80)throw Error('年度の範囲を確認してください．');if(f.get('netAnnual')===''&&(f.get('grossMin')===''||f.get('rate')===''))throw Error('年間手取り，または年収と手取り率を入力してください．');if(f.get('grossMax')!==''&&U.N(f.get('grossMax'))<U.N(f.get('grossMin')))throw Error('年収幅の上限を確認してください．');for(let y=a;y<=b;y++)p.years[y]=Object.fromEntries(['netAnnual','grossMin','grossMax','rate'].map(k=>[k,f.get(k)===''?null:U.N(f.get(k))]));persist('年度別の収入パターンを一括入力');});},
